window.kbPageData["views/entry/k-ae419c6fcf2d8561"] = {"key":"entry/k-ae419c6fcf2d8561","state":{"route":"entry/k-ae419c6fcf2d8561"},"node":{"id":"k-ae419c6fcf2d8561","mode":"k","title":"平均数同比增长率","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["平均数的同比增长率公式"],"qs":["国考 2025 副省级 行测#134","国考 2025 副省级 行测#135"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"directorySummary":"平均数同比增长率是本期平均数相对上年同期平均数的变动比例。平均数等于总量除以单位数，总量和单位数的同比增长率分别为 a 和 b 时，平均数同比增长率为 (a－b)/(1＋b)。","review":{"title":"平均数同比增长率","type":"原理与机制","definition":"平均数同比增长率是本期平均数相对上年同期平均数的变动比例。平均数等于总量除以单位数，总量和单位数的同比增长率分别为 a 和 b 时，平均数同比增长率为 (a－b)/(1＋b)。","explanation":"计算时，两期总量和单位数须采用一致的统计口径，两期单位数须为正，且上年同期总量须非零。由于 1＋b 为正，平均数是上升、下降还是持平，取决于 a－b 的符号。比较不同对象的平均数同比增速时，各对象的 1＋b 可能不同，须比较完整的比值。","basis":"据关联原题和解析编释。","references":[],"related":["k-7d44fefcbaab9e38"],"examFocus":{"国考 2025 副省级 行测#134":"用四个支付系统各自的业务金额和笔数同比增速，比较平均每笔金额的同比变化。","国考 2025 副省级 行测#135":"根据支付系统的业务金额和笔数变化，区分笔数增速、金额增速与平均每笔金额增速，并核对给定阈值。"}},"aspects":[{"title":"比较平均每笔金额的同比增速","uses":[{"unit":"Q1","role":"直接考查","use":"用2023年三季度四个支付系统各自的业务金额和笔数同比增速计算，①至④的平均每笔业务金额同比增速依次约为－13.71%、－10.44%、1.26%和44.04%，从高到低为④③②①，选C。","evidence":"按2023年三季度平均每笔业务金额同比增速从高到低排列","qids":["国考 2025 副省级 行测#134"]}]},{"title":"核验平均每笔金额的同比增速是否超过给定值","uses":[{"unit":"Q2","role":"解题依据","use":"网上支付跨行清算系统2023年三季度的业务金额同比增长5.38%，笔数同比下降0.03%，平均每笔金额同比增长约5.41%，因此A项可以推出。本题要求选出不能推出的一项，大额实时支付系统的业务金额占人民银行清算总中心系统业务总金额约94.73%，故选C。","evidence":"网上支付跨行清算系统处理业务平均每笔金额同比增长了5%以上","qids":["国考 2025 副省级 行测#135"]}]}]},"questions":{"国考 2025 副省级 行测#134":{"paper":"国考 2025 副省级 行测","n":134,"mod":"资料分析","src":["ffe12c35a46d4df574ec.pdf",27],"asrc":["ff0b352b44d417525086.pdf",42],"card":"0ea633ce21057776e228cb3f","links":[{"id":"k-ae419c6fcf2d8561","role":"解题依据","why":"设总金额和总笔数的同比增速分别为 a 和 b，则平均每笔金额的同比增速为 (a−b)/(1+b)。"}]},"国考 2025 副省级 行测#135":{"paper":"国考 2025 副省级 行测","n":135,"mod":"资料分析","src":["ffe12c35a46d4df574ec.pdf",28],"asrc":["ff0b352b44d417525086.pdf",42],"card":"0ea633ce21057776e228cb3f","links":[{"id":"k-ae419c6fcf2d8561","role":"解题依据","why":"设总金额和总笔数的同比增速分别为 a 和 b，则用 (a−b)/(1+b) 核验平均每笔金额的增速。"}]}},"terms":{"k-7d44fefcbaab9e38":{"id":"k-7d44fefcbaab9e38","mode":"k","type":"原理与机制","title":"平均数的增长率","qs":[],"count":2}},"references":{},"topics":[],"units":{"k-ae419c6fcf2d8561":[["国考 2025 副省级 行测#134"],["国考 2025 副省级 行测#135"]]}};
